          if (!isFinite(o) || !isFinite(h) || !isFinite(l) || !isFinite(c)) return;
          var t = Date.UTC(+dm[1], +dm[2] - 1, +dm[3]) / 1000;
          if (!Object.prototype.hasOwnProperty.call(byTime, t)) times.push(t);
          byTime[t] = { time: t, open: o, high: h, low: l, close: c, volume: isFinite(v) ? v : 0 };
