              if (!b || b.length < 5) return;
              var t = +b[0], o = +b[1], h = +b[2], l = +b[3], c = +b[4];
              if (!isFinite(t) || !isFinite(o) || !isFinite(h) || !isFinite(l) || !isFinite(c)) return;
              bars.push({ time: t, open: o, high: h, low: l, close: c, volume: +b[5] || 0 });
